        if buffer.len() < 4 + len {
            break;
        }
        messages.push(serde_json::from_slice(&buffer[4..4 + len]).map_err(|e| e.to_string())?);
        buffer.drain(..4 + len);
        if messages.len() >= 32 {
            break;
        }
    }
    Ok(messages)
}

